// Collision and motion rules reused from the supplied v174.103 race-physics module.
'use strict';
const LANE_W=3.90, RADIUS=1.86, MAX_STEP=1/100, EARTH_G=9.81;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
