    p.vz+=(target-p.vz)*(1-Math.exp(-2.1*dt));
    p.vz=clamp(p.vz,0,80);
    const diff=p.lane-p.x;
    p.vx+=(diff*13*grip-p.vx*6*grip)*dt;
    p.vx=clamp(p.vx,-6,6);
    p.x+=p.vx*dt;
    if(p.x<-.14){p.x=-.14;if(p.vx<0)p.vx*=-.23;}
    if(p.x>3.14){p.x=3.14;if(p.vx>0)p.vx*=-.23;}
