function assetGroup(path){
  if(path==='island.webp')return 'startup';
  if(path==='race.webp')return 'race';
  if(path==='raceExtra.webp')return 'race-extra';
  if(path==='ambient.mp3')return 'audio';
  if(path.startsWith('snails/'))return 'snails-'+Math.floor((Number(path.slice(7,10))-1)/24);
  return 'secondary';
}
function imagePath(path){
  const assets=globalThis.SNAIL_ASSETS;
  if(!assets)return './assets/'+path;
  if(!Object.hasOwn(assets,path)){
    const group=document.getElementById('asset-'+assetGroup(path));
    if(group){
      Object.assign(assets,JSON.parse(group.textContent));
      group.remove();
    }
  }
  return assets[path]??'./assets/'+path;
}

