    if(!this.renderer.lost&&(!this.renderer.images.has(atlas)||this.renderer.gl&&!this.renderer.textures.has(atlas)))
      throw Error('Scene texture is not ready: '+atlas);
    const was=this.active,previous=this.atlas;
    this.cancelCleanup();
    const canvas=this.renderer.canvas,buffer=[canvas.width,canvas.height];
