  const snail={ id:'s-'+int(n?.id,i+1,1), species:type, cls:int(n?.cls,species[type].cls,0,8),
    name:String(n?.nm??(Number(n?.sp)<0?n?.name??('Hibrid '+(i+1)):'')).slice(0,80),home:homes[n?.h]?.id??null,busy:null,
    hp:int(n?.hp,30,1,1e6),atk:int(n?.atk,5,1,1e6),speed:int(n?.spd,6,2,1e6),weight:int(n?.wt,3,1,1e6),
    prod:number(n?.prod,.5,0,1e6),beauty:int(n?.beauty,10,0,1e6),polish:int(n?.polish,0,0,40),
    trail:validTrail.has(n?.trail)?n.trail:'starry',sl:int(n?.sl,1,1,99),
    light:int(n?.light,0,0,5),originalWeight:int(n?.wtB,int(n?.wt,3,1,1e6),1,1e6),
    originalBeauty:int(n?.bea0,Math.max(0,int(n?.beauty,10)-int(n?.polish,0,0,40)*3),0,1e6),
    infusion:int(n?.inf,0,0,5),showWins:int(n?.pr,0),tempered:Boolean(n?.tempered),flaw:n?.fixed?null:legacyTrait(n?.fl),talent:legacyTrait(n?.tal)};
  if(n?.b)snail.baseStats={hp:number(n.b.hp,snail.hp,1,1e6),atk:number(n.b.atk,snail.atk,1,1e6),speed:number(n.b.spd,snail.speed,2,1e6),prod:number(n.b.prod,snail.prod,0,1e6)};
  return snail;
