/* screens get one wrapper after the title pill: the purple "room" of v174 */
const wrap=(html,key)=>{
  // Presentation-only scope; no duplicate menu/state or action dispatch.
  const shell='<div class="scr-body screen-'+escapeHtml(key)+'">';
  const end=html.indexOf('</header>');
  if(end<0)return shell+html+'</div>';
  let cut=end+9;
  if(html.startsWith('<p class="scr-sub">',cut))cut=html.indexOf('</p>',cut)+4;
  return html.slice(0,cut)+shell+html.slice(cut)+'</div>';
};
function renderPanel(key,s,view,now,moveKey){
  let html=screen(key,s,view,now);
  if(moveKey){
    const move='<button type="button" class="btn building-move" data-action="island-edit" data-value="'+escapeHtml(moveKey)+'" aria-label="Premesti na ostrvu" title="Premesti na ostrvu"><span aria-hidden="true">✥</span></button>';
    html=html.replace('</header>',move+'</header>');
  }
  return key==='settings'?html:wrap(html,key);
}
function screen(key,s,view,now){
  switch(key){
    case 'incubator':return incubator(s,now);
    case 'shop':return shop(s,view,now);
    case 'tree':return tree(s,view,now);
    case 'collection':return collection(s,view);
    case 'habitat':return habitat(s,view,now);
    case 'progress':return progress(s,now,view);
    case 'dimensions':return dimensionPanel(s);
    case 'login':return loginPanel(s,now);
    case 'profile':return profilePanel(s);
    case 'cloud':return cloudPanel(view);
    case 'settings':return settings(s,view);
    case 'help':return help();
    case 'island-menu':return more(s,now);
    case 'races':return races(s,view);
    case 'trophies':return trophyRoom(s,now);
    case 'analytics':return analytics(s,view);
    case 'arena':return arena(s,view);
    case 'reservoir':return reservoir(s,now);
    case 'wheat':return wheatPanel(s,now,view.wheatField??0);
    case 'breeding':return breeding(s,view);
    case 'crater':return crater(s,now);
    case 'pageant':return pageants(s,view);
    case 'expeditions':return expeditionsScreen(s,view,now);
    case 'timebreaker':return timebreaker(s,now);
    case 'mine':return header('Rudnik · zapušten')+
      info('Pećina sa polomljenim gredama. Rudarska proizvodnja još nije otključana; za sada je ovo znamenitost ostrva.');
    case 'fountain':return header('Fontana i vodopad')+
      info('Ukrasna fontana na ivici ostrva. Voda se preliva niz liticu. Nema dodatne ekonomije.');
    default:return header('Ostrvo')+info('Izaberi mesto na ostrvu.');
  }
}
function updateClockNodes(root,now){
  for(const n of root.querySelectorAll('[data-until]')){
    const until=Number(n.dataset.until);
    const value=now>=until?n.dataset.ready:timer(until-now);
    if(n.textContent!==value)n.textContent=value;
  }
  for(const meter of root.querySelectorAll('[data-incubation-start]')){
    const start=Number(meter.dataset.incubationStart),end=Number(meter.dataset.incubationEnd);
    const progress=incubationProgress(start,end,now);
    if(meter.value!==progress)meter.value=progress;
  }
}
