/* v0.8.11: postolje 1-3 i red za 4. mesto. Rivali bez trake traga: u trci se trag aktivira samo za igrača. */
function quickSlot(p,i,snail,badge=''){
  const isMe=i===0, sp=species[p.species];
  const colour=isMe?trailOf(snail)[1]:sp.color;
  const name=isMe?snailName(snail):sp.sr;
  const pic=isMe?snailPic(snail,false):snailPic({species:p.species},false);
  const time=p.finished!==null?p.finished.toFixed(2)+' s':'nije stigao';
  return '<div class="qslot'+(isMe?' me':'')+'" style="--q:'+colour+'"><span class="qrank">'+badge+'</span>'+pic+
    '<div class="qtxt"><b class="qname">'+escapeHtml(name)+'</b><div class="qbar"><i id="qr-bar-'+i+'"></i></div></div>'+
    '<div class="qnum"><b class="qpct" id="qr-pct-'+i+'">0%</b><small class="qtime">'+time+'</small></div></div>';
}
function quickResultPanel(value,race,snail,trace=[]){
  const name=tracks[race.key].name, place=race.finish.place;
  const order=race.players.map((p,i)=>({p,i})).sort((a,b)=>{
    const x=a.p,y=b.p;
    if(x.finished===null&&y.finished===null)return y.dist-x.dist;
    if(x.finished===null)return 1;
    if(y.finished===null)return -1;
    return x.finished-y.finished;
  });
  const badge=k=>order[k].i===0&&k<3?'<b class="qmedal m'+(k+1)+'">'+['Zlato','Srebro','Bronza'][k]+'</b>':'<b class="qplace">'+(k+1)+'</b>';
  const finalList=order.map((o,k)=>quickSlot(o.p,o.i,snail,badge(k))).join('');
  const live=race.players.map((p,i)=>quickSlot(p,i,snail)).join('');
  return popHead('Brza trka',name)+
    '<p class="mut center">'+race.finish.seconds.toFixed(2)+' s · '+race.impacts+' kontakata'+
    (value?' · '+value.reward+' sliza · '+value.xp+' XP':'')+'</p>'+
    (value?.practice?info('Trening · vreme je upisano u rekorde treninga.'):
      value&&!value.eligible?info('Dnevni limit nagrada je potrošen. Rekord se i dalje računa.'):'')+
    (!value?info('Rezultat nije sačuvan.'):'')+
    '<p class="mut center" id="qr-status" data-final="'+(place===1?'Pobeda!':'Cilj')+'">Trka traje…</p>'+
    '<div class="qlist" id="qr-bars">'+live+'</div><template id="qr-final">'+finalList+'</template>'+
    '<div class="acts">'+btn('quick-close','Na ostrvo','',true,'primary')+btn('quick-again','Još jedna','',true)+btn('open','Trkalište','races')+'</div>';
}
