modules.metrics=(()=>{
const { VERSION }=modules.domain;
const rounded = (n,d=1) => Math.round(n*10**d)/10**d;
function summarize(values) {
  if(!values.length)return {n:0};
  const sorted=values.slice().sort((a,b)=>a-b);
  const pick=p=>rounded(sorted[Math.ceil(p*sorted.length)-1]);
  return {n:values.length,p50:pick(.5),p95:pick(.95),p99:pick(.99),max:pick(1)};
}
function createMetrics(){
  const races=[],returns=[];
  const loading={};
  const islandCpu=new Float32Array(120);let islandN=0,islandWorst=0;
  let session=null,longTasks=0,longMax=0;
  // v147 race-frame history, sampled ONLY inside existing race renderer.
  // No parallel requestAnimationFrame, hidden-tab FPS or eval wrappers.
  const raceHistory=new Float32Array(120);
  let raceHistoryCount=0;
  const stalls=[];
  const addStall=(source,duration)=>{
    stalls.push({source,duration:rounded(duration),at:new Date().toISOString()});
    if(stalls.length>12)stalls.shift();
  };
  let active=true;
  try{
    const observer=new PerformanceObserver(list=>{
      for(const e of list.getEntries()){
        longTasks++;longMax=Math.max(longMax,e.duration);
        if(e.duration>=250)addStall('longtask',e.duration);
      }
    });
    observer.observe({type:'longtask',buffered:true});
  }catch{active=false;}
  function start(track,mode,backend,size,raceType,camera){
    session={track,mode,backend,size,raceType,camera,frames:[],cpu:[],calls:[],upload:[],ms:0,total:0,over50:0,worst:0};
  }
  function frame(gap,cpu,calls,upload){
    if(!session||!(gap>0))return;
    session.total+=1;session.ms+=gap;session.worst=Math.max(gap,session.worst);
    if(gap>50)session.over50++;
    if(gap>=250)addStall('race-frame',gap);
    raceHistory[raceHistoryCount++%raceHistory.length]=gap;
    if(session.frames.length>=16000)return;
    session.frames.push(gap);session.cpu.push(cpu);session.calls.push(calls);session.upload.push(upload);
  }
  function end(status){
    if(!session)return;
    const {track,mode,backend,size,raceType,camera,frames,cpu,calls,upload,ms,total,over50,worst}=session;
    races.push({track,mode,backend,size,raceType,camera,status,
      fps:ms?rounded(total*1000/ms):null,frames:summarize(frames),cpuMs:summarize(cpu),
      estimatedGpuCalls:summarize(calls),uploadedBytes:summarize(upload),over50,pctOver50:total?rounded(over50/total*100,2):0,
      worstFrameMs:rounded(worst),sampledN:frames.length,totalFrames:total});
    if(races.length>24)races.shift();
    session=null;
  }
  function islandDraw(cpu){
    if(!(Number.isFinite(cpu)&&cpu>=0))return;
    islandCpu[islandN++%islandCpu.length]=cpu;
    islandWorst=Math.max(islandWorst,cpu);
  }
  function mapReturn(samples){returns.push(samples);if(returns.length>24)returns.shift();}
  function markLoading(name,ms){if(Number.isFinite(ms))loading[name]=rounded(Math.max(0,ms));}
  function report(renderer){
    // Reverse the circular ring into chronological order only when requested.
    const count=Math.min(raceHistoryCount,raceHistory.length);
    const recentRaceFrameMs=new Array(count);
    for(let i=0;i<count;i++)recentRaceFrameMs[i]=rounded(
      raceHistory[(raceHistoryCount-count+i)%raceHistory.length]);
    return {version:VERSION,renderer,recentRaceFrameMs,stalls:stalls.slice(),
      environment:{width:innerWidth,height:innerHeight,dpr:devicePixelRatio},
      loading:{...loading},races:races.slice(),mapReturns:returns.slice(),
      islandDraw:{samples:islandN,cpu:summarize(Array.from(islandCpu.slice(0,Math.min(islandN,islandCpu.length)))),worstCpuMs:rounded(islandWorst)},
      longTasks:active?{count:longTasks,max:rounded(longMax)}:null};
  }
  return {start,frame,end,islandDraw,mapReturn,markLoading,report};
}

return {createMetrics};
})();
modules.cloud=(()=>{
// Single opt-in cloud backup adapter for the existing local save format.
// Publishable frontend key only; Row Level Security enforces user_id = auth.uid().
const endpoint='https://ehmukkowpqnjvwakxgvr.supabase.co';
const publishable='sb_publishable_UaRd4ExYyAs3nUKy3Rn0KA_Zfj57mE9';
let libraryPromise=null,client=null;
const originOk=()=>!globalThis.Capacitor?.isNativePlatform?.()&&
  (location.protocol==='https:'||location.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(location.hostname));
function library(){
  if(!libraryPromise)libraryPromise=import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.119.2/+esm')
    .catch(error=>{libraryPromise=null;throw error;});
  return libraryPromise;
}
async function getClient(){
  if(!originOk())throw Error('Cloud radi na HTTPS sajtu ili localhost-u, ne iz lokalnog fajla.');
  if(!client){
    const {createClient}=await library();
    client=createClient(endpoint,publishable,{auth:{storageKey:'snail-city-new-cloud-auth-v1',
      persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}});
  }
  return client;
}
async function identity(create=false){
  const sdk=await getClient();
  const {data:sessionResult,error:sessionError}=await sdk.auth.getSession();
  if(sessionError)throw sessionError;
  if(!sessionResult?.session){
    if(!create)return {sdk,user:null};
    const signed=await sdk.auth.signInAnonymously();
    if(signed.error)throw signed.error;
  }
  // Verify with the server rather than trusting cached local session metadata.
  const verified=await sdk.auth.getUser();
  if(verified.error)throw verified.error;
  if(!verified.data?.user?.id)throw Error('Cloud sesija nije verifikovana.');
  return {sdk,user:verified.data.user};
}
async function status(create=false){
  const {sdk,user}=await identity(create);
  if(!user)return {account:null};
  const {data,error}=await sdk.from('sc_player_saves')
    .select('revision,schema_version,updated_at').eq('user_id',user.id).maybeSingle();
  if(error)throw error;
  if(data&&Number(data.schema_version)!==1)
    throw Error('Cloud sejv ima nepoznatu šemu. Podaci nisu izmenjeni.');
  return {account:{id:user.id,version:Number(data?.revision??0),exists:Boolean(data),updatedAt:data?.updated_at??null}};
}
async function upload(save,expected,exists=false){
  const {sdk,user}=await identity();
  if(!user)throw Error('Prvo poveži cloud profil.');
  if(!Number.isSafeInteger(expected)||expected<0)throw Error('Nedostaje validna cloud revizija.');
  const record={schema_version:1,save_data:save,updated_at:new Date().toISOString(),revision:expected+1};
  let data,error;
  if(!exists){
    ({data,error}=await sdk.from('sc_player_saves').insert({user_id:user.id,...record}).select('revision,updated_at').maybeSingle());
  }else{
    ({data,error}=await sdk.from('sc_player_saves').update(record)
      .eq('user_id',user.id).eq('revision',expected).select('revision,updated_at').maybeSingle());
  }
  if(error?.code==='23505'||!error&&!data)throw Error('Cloud kopija je promenjena na drugom uređaju. Osveži podatke pre slanja; nijedan sejv nije prepisan.');
  if(error)throw error;
  return {account:{id:user.id,version:Number(data.revision),exists:true,updatedAt:data.updated_at}};
}
async function deleteCopy(expected){
  const {sdk,user}=await identity();
  if(!user)throw Error('Cloud sesija nije aktivna.');
  if(!Number.isSafeInteger(expected)||expected<0)throw Error('Cloud kopija nije potvrđena.');
  const {data,error}=await sdk.from('sc_player_saves').delete()
    .eq('user_id',user.id).eq('revision',expected).select('revision').maybeSingle();
  if(error)throw error;
  if(!data)throw Error('Cloud kopija je promenjena na drugom uređaju. Obrisano nije ništa.');
  return {account:{id:user.id,version:0,exists:false,updatedAt:null}};
}
async function signOut(){
  const sdk=await getClient();
  const {error}=await sdk.auth.signOut();
  if(error)throw error;
}
async function download(){
  const {sdk,user}=await identity();
  if(!user)throw Error('Cloud sesija nije aktivna.');
  const {data,error}=await sdk.from('sc_player_saves')
    .select('save_data,revision,schema_version,updated_at').eq('user_id',user.id).maybeSingle();
  if(error)throw error;
  if(!data)throw Error('Cloud kopija još ne postoji.');
  if(Number(data.schema_version)!==1)throw Error('Nepodržana verzija cloud sejva.');
  return {save:data.save_data,account:{id:user.id,version:Number(data.revision),exists:true,updatedAt:data.updated_at}};
}
return {originOk,library,status,upload,download,deleteCopy,signOut};
})();
