function settingsWrite(){try{localStorage.setItem('snail-city-rebuild.preferences',JSON.stringify({quality:view.quality,music:view.music,theme:view.theme,lang:view.lang}));}catch{}}
// v174 analytics: measured only on this device, kept outside the save (key below), never sent anywhere.
const AN_KEY='snail-city-rebuild.analytics';
const CUR_KEYS=['sliz','diamonds','tokens','dust','stones','fragments','wheat'];
const analytics=(()=>{
  let a=null;
  try{a=JSON.parse(localStorage.getItem(AN_KEY)??'null');}catch{}
  if(!a||typeof a!=='object')a={};
  return {sess:a.sess??0,secs:a.secs??0,acts:a.acts??{},scr:a.scr??{},lv:Array.isArray(a.lv)?a.lv:[]};
})();
let analyticsDirty=false;
view.analytics=analytics;
function analyticsSave(){
  if(!analyticsDirty)return;
  analyticsDirty=false;
  try{localStorage.setItem(AN_KEY,JSON.stringify(analytics));}catch{}
}
function analyticsLog(type,before,after){
  const row=analytics.acts[type]??={n:0};
  row.n++;
  for(const key of CUR_KEYS){
    const d=(after[key]??0)-(before[key]??0);
    if(d>0)row[key+'+']=(row[key+'+']??0)+d;else if(d<0)row[key+'-']=(row[key+'-']??0)-d;
  }
  if(after.level>before.level)analytics.lv.push([+(analytics.secs/3600).toFixed(2),after.level]);
  if(analytics.lv.length>200)analytics.lv.splice(0,analytics.lv.length-200);
  analyticsDirty=true;
}
function measureReport(){
  const report=metrics.report({...renderer.estimate(),nodes:document.getElementsByTagName?.('*').length??null,
    jsHeapMB:performance.memory?+(performance.memory.usedJSHeapSize/1048576).toFixed(1):null});
  report.sceneLifecycle=sceneManager?.stats()??null;
  report.assets=modules.renderer.imageHealth();
  const gl=renderer.gl,conn=navigator.connection??{};
  let gpu=null;
  if(gl){try{gpu={name:String(gl.getParameter(gl.RENDERER)||''),
    version:String(gl.getParameter(gl.VERSION)||''),maxTexture:gl.getParameter(gl.MAX_TEXTURE_SIZE),
    lost:gl.isContextLost()};}catch{gpu={lost:renderer.lost};}}
  report.device={screen:innerWidth+'×'+innerHeight,dpr:devicePixelRatio||1,
    cpu:navigator.hardwareConcurrency??null,ram:navigator.deviceMemory??null,gpu,
    net:{online:navigator.onLine,type:conn.effectiveType??null,rtt:conn.rtt??null,
      down:conn.downlink??null,saver:Boolean(conn.saveData)}};
  return report;
}
function updateStatus(){
  if(!s)return;
  if(view.devOpen)renderDev();
  set($('level'),s.level);
  for(const resource of CUR_KEYS)set($(resource),format(s[resource]??0));
  $('wheat-chip').hidden=s.level<WHEAT_LEVEL;

  const mx=xpNeeded(s.level);$('xp-meter').max=mx;$('xp-meter').value=Math.min(mx,s.xp);
  set($('xp-amount'),format(s.xp)+' / '+format(mx)+' XP');
  set($('build-info'),VERSION+' · '+(renderer?.backend??''));
  activityBadge();
  let goal;
  const again=Boolean(s.tutorial?.repeat), early=s.level<3||again;
  if(early&&s.tutorial&&!s.tutorial.collected)
    goal=['Sakupi sliz','Staništa pune Rezervoar dok igraš i dok si van igre.','U rezervoar','reservoir'];
  else if((s.level<3||again&&!s.tutorial.hatched)&&s.eggs.some(egg=>egg.kind!==8))
    goal=['Izlezi puža','Spremna jaja donose puža i XP. Otvori inkubator i proveri vreme.','U inkubator','incubator'];
  else if(s.level<3||again&&!s.tutorial.hatched)
    goal=['Kupi standardno jaje','Izlezi jaja za XP do nivoa 3.','U prodavnicu','shop'];
  else if(!s.built.includes('races'))
    goal=['Otvori Trkalište','Izgradi Trkalište za 6.000 sliza.','U trkalište','races'];
  else if(s.tutorial&&!s.tutorial.raced)
    goal=['Završi svoju prvu trku','Izaberi puža i stazu pa pređi cilj u ligi.','U trkalište','races'];
  const card=$('island-goal');
  if(card)card.hidden=!goal;
  if(goal){
    set($('goal-title'),goal[0]);set($('goal-text'),goal[1]);set($('goal-action'),goal[2]);
    $('goal-action').dataset.value=goal[3];
  }
}
